DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef(oid) INTO definition FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='reward_v366_insert_guard'; definition:=replace(definition,'AND day_key=NEW.day_key AND reason IN','AND day_key=NEW.day_key AND provenance_state=''VERIFIED'' AND reason IN'); EXECUTE definition; SELECT pg_get_functiondef(oid) INTO definition FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='award_referral_milestone_v366'; definition:=replace(definition,'AND verified_activity_id IS NOT NULL','AND verified_activity_id IS NOT NULL AND provenance_state=''VERIFIED'''); EXECUTE definition; SELECT pg_get_functiondef(oid) INTO definition FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='confirm_reward_funding_snapshot'; definition:=replace(definition,'DECLARE s reward_funding_snapshots%ROWTYPE; r jsonb; labelled jsonb;','DECLARE s reward_funding_snapshots%ROWTYPE; r jsonb; labelled jsonb;'); definition:=replace(definition,'  IF p_role <> ''super_admin'' THEN', '  IF NOT EXISTS(SELECT 1 FROM public.app_admins WHERE email=lower(p_email) AND role=''super_admin'' AND NOT disabled) OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_actor AND lower(email)=lower(p_email)) THEN RAISE EXCEPTION ''Current super admin required''; END IF; IF p_role <> ''super_admin'' THEN'); definition:=replace(definition,'  IF p_expected_hash IS DISTINCT FROM s.snapshot_hash THEN','  PERFORM 1 FROM public.flow_points_ledger WHERE id=ANY(s.ledger_ids) ORDER BY id FOR UPDATE; PERFORM 1 FROM public.profiles WHERE id IN (SELECT user_id FROM public.flow_points_ledger WHERE id=ANY(s.ledger_ids)) ORDER BY id FOR SHARE; IF EXISTS(SELECT 1 FROM public.flow_points_ledger WHERE id=ANY(s.ledger_ids) AND reason IN (''CORE_SWAP'',''CORE_SWAP_V2'') AND provenance_state<>''VERIFIED'') THEN RAISE EXCEPTION ''Independent reward provenance required''; END IF; IF p_expected_hash IS DISTINCT FROM s.snapshot_hash THEN'); EXECUTE definition; END $$;